const detected = $input.all();
const count = detected.length;
if (count === 0) return [];

// A/B subject line rotation by ISO week number
const weekNum = Math.floor(Date.now() / (7 * 24 * 3600 * 1000));
const subject = weekNum % 2 === 0
  ? 'Restox found products you reorder regularly'
  : "You're reordering these — Restox can automate them";

// Generate unsubscribe token: base64url(userId) + '.' + hmac(userId, secret).slice(0,32)
const crypto = require('crypto');
const userId = $('Split Into Users').item.json.id;
const email  = $('Split Into Users').item.json.email;
const secret = process.env.SUPABASE_SERVICE_ROLE_KEY || 'YOUR_SUPABASE_SERVICE_ROLE_KEY';
const payload = Buffer.from(userId).toString('base64url');
const sig     = crypto.createHmac('sha256', secret).update(userId).digest('hex').slice(0, 32);
const token   = `${payload}.${sig}`;
const unsubUrl = `https://restox.net/api/nudge/unsubscribe?token=${encodeURIComponent(token)}`;

return [{ json: { userId, email, count, subject, unsubUrl } }];

